function ActivityMountainOptionEntryDialog:OnInitialize()
	---@type Engine.Lib.CoWait
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		xTry(function()
			if not isNull(self.controller.Argument.extra) then
				self.isPlay = checkNumber(self.controller.Argument.extra) == 1
			else
				self.isPlay = false
			end
			if not self.isPlay then
				CfUtils.RefreshTopGoods({ })
				self.controller:SetExtraArgument(1)
			end
			local aniName = self.isPlay and "ActivityMountainOptionEntryDialog_Entry" or "ActivityMountainOptionEntryDialog_LoadEntry"
			CfUtils.PlayAnimation(self.controller, aniName)
			self.parameters = self.controller.Argument.parameters
			self.activityData = self.parameters.activityData
			self.co = cs_coroutine.start(function()
				local time = CfUtils.GetAnimationTime(self.controller,aniName)
				cs_coroutine.yield_return(CS.UnityEngine.WaitForSeconds(time - 1))
				self:RequestShow()
			end)
		end)
	end))
	return coWait
end

function ActivityMountainOptionEntryDialog:OnFinalize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		xTry(function()
			self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
			if isNotNull(self.co) then
				cs_coroutine.stop(self.co)
				self.co = nil
			end
			self:Delete()
			self = nil --lua层的gc需要    
		end)
	end))
	return coWait
end

