function ActivityMountainOptionEntryDialog:SetTimeShow()
	--region 时间
	local startTime =  self.activityData.startTime
	local closeTime =  self.activityData.closeTime
	local ActivityUtils         = import("Game.Activity.ActivityUtils")
	CfUtils.FillText(self.TextTime, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
	-- CfUtils.FillText(self.TextTime, os.date("%Y.%m.%d", startTime).."-"..os.date("%Y.%m.%d  %H:%M", closeTime))
end

function ActivityMountainOptionEntryDialog:RequestShow()
	GameUtils.Request(Interfaces.OverseaActivityCatParadiseHome,{ activityUuid = self.activityData.id},function(request,response)
		if response.errCode == 0 then
			ActivityCakeUtils.GetActivityCakeMgr():InitialDojo(response.data)
			self.requestSuccess = true
			local isPlayChapter = checkNumber(CfUtils.GetLocalData(self:GetLocalDataKey(),0)) == 1
			if not isPlayChapter then
				self:OnBtnPlayClick()
			end
			self:Refresh(response.data)
		end
	end)
end

function ActivityMountainOptionEntryDialog:GetLocalDataKey()
	if isNull(self.localDataKey) then
		self.localDataKey = string.format("ActivityMountainOptionEntryDialog_%s",self.activityData.id)
	end
	return self.localDataKey
end

function ActivityMountainOptionEntryDialog:OnBtnExchangeClick()
	local id = self:GetIdByIndex(4)
	local isUnLock = self:IsUnLockFuncById(id)
	if isUnLock then
		CS.Engine.UI.UIModule.OpenDialog({ id = self:GetModuleId(id)},{{id = self.controller.Argument.id }})
	else
		local des = self:GetUnLockDes(id)
		GameUtils.Toast(des)
	end
end

function ActivityMountainOptionEntryDialog:IsActivityClose()
	---@type PlayerComponent
	local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
	if not comp then
		return
	end
	local curTime = comp:GetPlayerDojo():GetServerTime()
	curTime = curTime or os.time()
	return curTime > self.activityData.endTime
end

