function ActivityMountainOptionEntryDialog:IsUnLockFuncById(id)
	local homeDojo = ActivityCakeUtils.GetActivityCakeMgr():GetActivityDojo()
	return homeDojo:IsBtnUnLock(id)
end

function ActivityMountainOptionEntryDialog:GetModuleId(id)
