function ActivityMountainOptionEntryDialog:GetUnLockDes(id)
	local homeDojo = ActivityCakeUtils.GetActivityCakeMgr():GetActivityDojo()
	local chapterId = homeDojo:GetUnLockChapterId(id)
	local vo = CfUtils.GetCfVo(AutoIds.IdSetting6240, "ActivityCakeMainLineLevelVo", chapterId)
	if not isNull(vo) then
		return localize("通关故事模式_levelName_后解锁",{_levelName_ = vo.levelName})
	end
	return ""
end

function ActivityMountainOptionEntryDialog:OnBtnPlayClick()
	local homeDojo = ActivityCakeUtils.GetActivityCakeMgr():GetActivityDojo()
	local scheduleVo = homeDojo.scheduleConf
	local ChapterUtils = import('Game.Chapter.ChapterUtils')
	local URPCameraController =  CS.Game.Native.URP.URPCameraController.Instance
	ChapterUtils.ProcessChapter(checkNumber(scheduleVo.storyId), function(go)
		self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
		URPCameraController:SetMainCameraActive(false)
		self._plotGo = go
	end, function()
		self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
		URPCameraController:SetMainCameraActive(true)
		CfUtils.WriteLocalData(self:GetLocalDataKey(),1)
		ActivityCakeUtils.PlayBgm()
		CfUtils.SafeDelete(self._plotGo)
	end)
end

function ActivityMountainOptionEntryDialog:GetIdByIndex(index)
	return self.activityData.activityContentId * 100 + index
end

return ActivityMountainOptionEntryDialog